"""Fifteen Russian slides with speaker notes, generated only from saved evidence."""
from pathlib import Path
import json,re
import pandas as pd

ROOT=Path(__file__).resolve().parents[1]

def main():
    m=json.loads((ROOT/'results/metrics.json').read_text(encoding='utf-8'));d=pd.read_csv(ROOT/'dataset.csv')
    p=pd.read_csv(ROOT/'results/test_predictions.csv');history=pd.read_csv(ROOT/'results/training_history.csv')
    meta=json.loads((ROOT/'models/metadata.json').read_text(encoding='utf-8'));selected=m['selected_model'];s=m['test'][selected]
    bootstrap=json.loads((ROOT/'results/bootstrap.json').read_text(encoding='utf-8'));ci=bootstrap['macro_f1_95_percentile_interval']
    demo=json.loads((ROOT/'results/demo_metadata.json').read_text(encoding='utf-8'));errors=int((p.actual!=p[selected]).sum())
    classes=pd.read_csv(ROOT/'results/classification_report.csv').set_index('class')
    accounting=pd.read_csv(ROOT/'results/error_accounting.csv')
    names={'majority':'Всегда car','logistic':'Логистическая','random_forest':'Случайный лес'}
    groups=d.groupby('split').scene_group.nunique();counts=d['class'].value_counts()
    chosen=history.loc[(history.model==selected)&history.parameters.map(lambda x:json.loads(x)==meta['parameters'][selected])].iloc[0]
    slides=[]
    def add(layout,title,notes,source,**kwargs):slides.append(dict(layout=layout,title=title,notes=notes,source=source,**kwargs))
    add('cover','Классификация транспорта: что доказали данные',
        'Исходная тема посвящена классификации транспорта с видеорегистратора. В выполненной работе основное измерение качества проведено на реальных размеченных фотографиях COCO. Отдельно подготовлена демонстрация применения модели к вручную выделенным областям реального дорожного видео. Эти части отвечают разным вопросам и должны быть представлены раздельно. Местная выборка Атырау не получена, поэтому готовность городской системы не заявляется. Код, вычисления и текст подготовлены с раскрываемой помощью ИИ; перед защитой студенту необходимо самостоятельно проверить результаты и понять методику.',
        'Lin et al., Microsoft COCO (2014); исходный кейс №15.',subtitle='Кейс №15 · COCO + реальное видео · редакция 26.09.2026',body=['Три класса: car, bus, truck','Локальная оценка Атырау отсутствует','Статус: PARTIAL'])
    add('columns','Задача: определить тип уже выделенного объекта',
        'На вход подаётся цветной фрагмент изображения по исходной рамке COCO. На выходе получается один из трёх классов. Таким образом, проверяется классификация объекта, а не его обнаружение на полном кадре. В исследование не включены фон, мотоциклы, велосипеды и неизвестные категории. Главный вопрос состоит в том, распознаёт ли обученная модель все классы лучше простого правила большинства. Отдельно рассматриваются характер ошибок и границы переноса на видеорегистратор. Предсказание на демонстрационном кропе не является эталонной меткой.',
        'Report.md, разделы 2 и 7; COCO instances_val2017.',columns=[{'title':'Измеряем','body':'Macro-F1, accuracy и ошибки трёх классов на отложенных фотографиях.'},{'title':'Требует нового исследования','body':'Обнаружение на видео, трекинг и точность на дорогах Атырау.'}])
    add('stat','Реальная выборка, но не городской транспортный поток',
        'Каждая строка индекса соответствует одному размеченному объекту. Несколько строк могут происходить из одной фотографии, поэтому объекты нельзя считать независимыми дорожными наблюдениями. Легковые автомобили представлены чаще автобусов и грузовиков. Это объясняет необходимость равновзвешенной по классам метрики. Однако состав выбранных фотографий ничего не говорит о долях транспорта в Атырау: география, поездки и время наблюдения не установлены. Исходные метки взяты из COCO, а не созданы прогнозами нашей модели. Атрибуция каждого изображения сохранена в отдельном файле.',
        'COCO val2017; dataset.csv; results/class_counts.csv.',metrics=[{'value':str(len(d)),'label':'размеченных объектов'},{'value':str(d.image_id.nunique()),'label':'исходных фотографий'},{'value':str(counts['car']),'label':'car'},{'value':str(counts['bus']+counts['truck']),'label':'bus + truck'}])
    funnel=pd.read_csv(ROOT/'results/selection_funnel.csv')
    add('table','Отбор данных полностью восстанавливается',
        'Таблица показывает последовательность фильтрации, а не пересекающиеся причины исключения. Сначала выбраны три категории транспорта, затем допустимые для выбранной учебной обработки лицензии, объекты без crowd-разметки и рамки достаточного размера. Все подходящие фотографии успешно получены. При повторном запуске ошибка загрузки теперь останавливает работу, чтобы состав теста незаметно не изменился. Фильтр размера также ограничивает применимость: маленькие дальние машины, обычные для видеорегистратора, почти не представлены. Этот компромисс нельзя скрывать за чистотой подготовленного набора.',
        'Исходный JSON COCO; results/selection_funnel.csv.',table={'headers':['Этап','Объекты','Фото'],'rows':[[str(r.iloc[0]),int(r.iloc[1]),int(r.iloc[2])] for _,r in funnel.iterrows()]})
    add('columns','Лицензия аннотаций не заменяет лицензию фотографии',
        'Лицензии выбранных изображений проверены по исходным метаданным COCO. В наборе оставлены четыре варианта Creative Commons, допускающие обработку при соответствующих условиях; изображения с запретом производных исключены. Для каждой строки сохранены исходные ссылки, название лицензии и указание на кроп. При этом COCO не предоставил имена авторов и оригинальные названия фотографий. Эти сведения явно обозначены как отсутствующие. Повторная проверка подтвердила совпадение полей с источником, но не устраняет ограничение атрибуции и не является юридическим подтверждением публичного распространения.',
        'COCO Terms of Use; results/image_attribution.csv; CC 2.0.',columns=[{'title':'Сохранено','body':'CC BY, BY-SA, BY-NC, BY-NC-SA 2.0; ссылки Flickr и условия каждой фотографии.'},{'title':'Ограничение','body':'Имена авторов отсутствуют в JSON. Для публикации нужна дополнительная проверка атрибуции.'}])
    add('stat','Все объекты одной фотографии остаются вместе',
        'Разбиение выполнено по исходным фотографиям с дополнительной проверкой похожих изображений через перцептивный хеш. Объекты одной фотографии и одной объединённой группы не могут попасть одновременно в обучение и тест. Использованы пять частей StratifiedGroupKFold, но только для создания одного фиксированного разбиения; пятифолдовая оценка качества не заявляется. Точные копии кропов между частями отсутствуют. Такая проверка уменьшает риск утечки, однако не доказывает независимость физических мест или поездок: соответствующие метаданные отсутствуют. Пропорции частей больше не подбирались после просмотра результата.',
        'results/split_manifest.csv; results/split_protocol.json; seed 42.',metrics=[{'value':str(int((d.split=='train').sum())),'label':f'train · {groups["train"]} групп'},{'value':str(int((d.split=='validation').sum())),'label':f'validation · {groups["validation"]} групп'},{'value':str(int((d.split=='test').sum())),'label':f'test · {groups["test"]} групп'}])
    add('columns','Обучено пять конфигураций; выбор сделан по validation',
        'Каждый кроп преобразуется в HOG, цветовые гистограммы и отношение сторон. Идентификаторы, лицензии и путь к файлу в признаки не входят. Логистическая регрессия проверена с тремя значениями регуляризации, случайный лес с двумя ограничениями глубины. Средние и масштабы StandardScaler вычислены только по обучающим объектам, что подтверждено повторным расчётом. Лучшей по валидационному macro-F1 стала логистическая модель с C равным единице. Она не переобучалась на объединении train и validation. Все веса получены здесь; предобученные нейросети не использовались.',
        'Dalal & Triggs (2005); training_history.csv; models/metadata.json.',columns=[{'title':'Признаки и модели','body':f'{m["features"]} признаков: HOG + RGB + форма. Majority, логистическая регрессия, случайный лес.'},{'title':'Критерий выбора','body':f'Macro-F1 validation = {m["validation"][selected]["macro_f1"]:.3f}. Logistic C = {meta["parameters"]["logistic"]["C"]:g}; scaler только train.'}])
    add('chart','Macro-F1 выросла, общая доля верных ответов — нет',
        'На диаграмме все модели оцениваются на одних и тех же отложенных объектах. Macro-F1 даёт каждому классу одинаковый вес, а accuracy считает общую долю правильных ответов. Логистическая модель выигрывает у правила большинства по первой метрике, но совпадает с ним по второй. Лес показывает наибольшую accuracy, однако хуже распознаёт меньшие классы и имеет меньший macro-F1. Поскольку критерий выбора был установлен заранее, лес не объявляется победителем задним числом. Следующий слайд показывает точные количества, которые объясняют это различие.',
        'results/metrics.json; scikit-learn f1_score documentation.',chart={'categories':[names[x] for x in ['majority','logistic','random_forest']],'series':[{'name':'Macro-F1','values':[m['test'][x]['macro_f1'] for x in ['majority','logistic','random_forest']]},{'name':'Accuracy','values':[m['test'][x]['accuracy'] for x in ['majority','logistic','random_forest']]}]},body=f'Одинаковый test: {len(p)} объектов. Модель выбрана до просмотра test.')
    rows=[]
    for name in ['majority','logistic','random_forest']:
        a=accounting.loc[accounting.model==name].set_index('class');vals=[int(a.loc[c,'correct']) for c in ['bus','car','truck']];rows.append([names[name],*vals,sum(vals)])
    add('table','Одинаковая accuracy скрывает разные ошибки',
        'Правило большинства правильно называет все легковые автомобили и полностью пропускает автобусы и грузовики. Логистическая модель распознаёт четырнадцать автобусов и десять грузовиков, но теряет двадцать четыре правильных ответа на автомобилях. Эти изменения точно компенсируются в общей accuracy. Случайный лес почти восстанавливает распознавание автомобилей, но правильно называет лишь шесть автобусов и четыре грузовика. Поэтому таблица нагляднее одного итогового процента. Для равного учёта типов транспорта нужен анализ каждого класса и заранее выбранная метрика, а не только максимальное общее число совпадений.',
        'results/error_accounting.csv; test_predictions.csv.',table={'headers':['Модель','bus','car','truck','Всего'],'rows':rows},body='Число верных ответов по истинному классу')
    add('figure','Грузовики: пропуски и ложные срабатывания одновременно',
        'Строки матрицы соответствуют истинному классу, столбцы — прогнозу. Из тридцати двух грузовиков верно названы десять; тринадцать приняты за легковые автомобили, девять за автобусы. Обратная ошибка также важна: среди двадцати девяти ответов truck только десять верны. Поэтому нельзя просто сложить прогнозы и получить надёжное число грузовиков в потоке. Автобусы тоже имеют и пропуски, и ложные срабатывания. Матрица рассчитана для правильных исходных рамок, следовательно ошибки будущего детектора добавятся к уже измеренным ограничениям классификации.',
        'results/confusion_matrix.csv; classification_report.csv.',figure='figures/confusion_matrix.png',body=[f'Ошибок: {errors} из {len(p)}',f'Recall truck: {classes.loc["truck","recall"]:.1%}',f'Precision truck: {classes.loc["truck","precision"]:.1%}'])
    add('figure','Примеры ошибок показывают вход модели',
        'На рисунке представлены первые шесть ошибочных объектов в фиксированном порядке идентификаторов. Они не отбирались ради эффектного объяснения или улучшения впечатления о модели. Показывается вход после преобразования к размеру шестьдесят четыре на шестьдесят четыре пикселя. Сжатие, ракурс и сходство форм могут затруднять классификацию, но их отдельный вклад здесь не измерен. Для причинного вывода потребовалась бы независимая разметка этих условий. Каждый пример связан с исходной фотографией и лицензией через идентификатор; изображения не являются синтетическими иллюстрациями.',
        'results/errors.csv; image_attribution.csv.',figure='figures/error_examples.png',body=['Порядок по ID, без отбора удобных примеров','Ракурс и заслонение отдельно не размечены'])
    add('stat','Почти идеальный train не означает надёжный test',
        'Сильный разрыв между обучением и отложенными данными указывает на переобучение при большом числе признаков и небольшом разнообразии фотографий. Мы не заменяем этот результат новой настройкой после знакомства с test. Описательная неопределённость оценена повторными выборками целых тестовых групп, чтобы не считать несколько кропов одной фотографии независимыми. Полученный диапазон относится к текущему источнику и не гарантирует работу на улицах Атырау. Отдельный статистический тест превосходства над baseline не проводился. Следующее улучшение следует проверять на новых заранее отложенных поездках.',
        'training_history.csv; results/bootstrap.json: 500 групповых повторов.',metrics=[{'value':f'{chosen.train_macro_f1:.3f}','label':'macro-F1 train'},{'value':f'{m["validation"][selected]["macro_f1"]:.3f}','label':'macro-F1 validation'},{'value':f'{s["macro_f1"]:.3f}','label':'macro-F1 test'},{'value':f'{ci[0]:.3f}–{ci[1]:.3f}','label':'описательный bootstrap-диапазон'}])
    add('figure','30 секунд реального видео: демонстрация применения',
        'Видео опубликовано автором Fernost на Wikimedia Commons с обозначением CC0. В демонстрации используется непрерывный фрагмент исходника и две вручную заданные области с отдельными временными метками. Классы в боковой панели вычислены сохранённой моделью; это прогнозы, а не независимые эталонные ответы. Статические примеры не выдаются за автоматическое обнаружение объектов на текущем кадре. География съёмки не установлена, поэтому видео нельзя подписывать как Атырау. Ссылка открывает соседний файл demo.mp4. Количественная оценка качества видео и скорости полного конвейера отсутствует.',
        'Fernost, Dashcam Recording (urban), Wikimedia Commons, CC0 (2013).',figure='figures/demo_frame.png',body=[f'{demo["output_duration_seconds"]:.0f} секунд · {demo["frames_decoded"]} кадров','Два ручных кропа; география неизвестна','Нет detector, tracking и тестовой разметки'],link={'text':'Открыть видео','target':'demo.mp4'})
    add('conclusion','Следующий шаг — новые размеченные поездки Атырау',
        'Работа дала воспроизводимый результат на реальных изображениях и показала ограничения простой классификации. Логистическая модель лучше распределяет качество между классами, но не повышает общую долю верных ответов относительно большинства. Для локального продолжения нужны разрешённые независимые поездки с разметкой типов транспорта и разделением по поездкам. Следует отдельно измерить качество обнаружения рамок, классификации и подсчёта уникальных машин. Новый тест надо зафиксировать до настройки. Текущий тест уже изучен, поэтому любые новые решения требуют прозрачного последующего эксперимента, а не переименования старого результата.',
        'Report.md, разделы 9–12; results/revision_checks.json.',body=['Сохранить отрицательные и слабые результаты','Разделять новые данные по поездкам','Оценить детектор и классификатор отдельно','Статус PARTIAL сохраняется'])
    add('references','Источники и проверяемые доказательства',
        'Основные научные источники описывают набор COCO и признаки HOG; мы не переносим их опубликованные результаты на собственную задачу без измерения. Условия использования фотографий проверяются отдельно от лицензии аннотаций. Источник демонстрационного видео и его автор указаны явно. Полные адреса, даты обращения и доступные сведения об атрибуции приведены в References и отдельных таблицах пакета. Для проверки чисел следует открыть сохранённые прогнозы, метрики, историю обучения и журнал повторного аудита. Эти файлы позволяют воспроизвести вычисления, но не заменяют отсутствующую местную выборку.',
        'References.md; SOURCES.csv; results/REVISION_AUDIT_20260926.md.',body=['Lin et al. Microsoft COCO: Common Objects in Context, 2014 [V03]','Dalal & Triggs. Histograms of Oriented Gradients, CVPR 2005 [V04]','COCO Terms of Use; CC BY / SA / NC 2.0 [V02, V10–V13]','Fernost. Dashcam Recording (urban), 2013; CC0 [V08]','Числа: metrics.json, test_predictions.csv, training_history.csv'])
    for i,slide in enumerate(slides,1):
        assert len(slide['title'])<=65,(i,len(slide['title']))
        words=len(slide['notes'].split())
        assert 60<=words<=110,(i,words)
        if 'figure' in slide:assert (ROOT/slide['figure']).is_file(),slide['figure']
        if 'link' in slide:assert (ROOT/slide['link']['target']).is_file(),slide['link']
    assert 13<=len(slides)<=15
    (ROOT/'slides_v2.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    summary_path=ROOT/'summary.json'
    if summary_path.exists():
        summary=json.loads(summary_path.read_text(encoding='utf-8'));summary.update({'slides':len(slides),'slides_source':'slides_v2.json','revision_date':'2026-09-26'});summary_path.write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
    validation={'slides':len(slides),'layouts':[s['layout'] for s in slides],'title_lengths':[len(s['title']) for s in slides],'notes_word_counts':[len(s['notes'].split()) for s in slides],'relative_assets_exist':True,'metrics_source':'results/metrics.json','status':'PASS'}
    (ROOT/'results/slides_v2_checks.json').write_text(json.dumps(validation,ensure_ascii=False,indent=2),encoding='utf-8')
    print('slides_v2 PASS:',len(slides),'slides')

if __name__=='__main__':main()
